const state={view:'dashboard',devices:[],filters:{query:'',estado:''}};
const navItems=[['dashboard','Dashboard'],['inventory','Inventario LDU'],['incidents','Incidencias'],['stock','Stock'],['history','Historial IMEI'],['settings','Configuración']];
document.addEventListener('DOMContentLoaded',()=>{renderNav();navigate('dashboard')});
function renderNav(){document.querySelector('#main-nav').innerHTML=`<div class="nav-group">Principal</div>${navItems.map(([id,label])=>`<button class="nav-item" data-view="${id}">${label}</button>`).join('')}`;document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)))}
function navigate(view){state.view=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#page-title').textContent=navItems.find(x=>x[0]===view)?.[1]||'Sistema LDU';if(view==='dashboard')renderDashboard();else if(view==='inventory')renderInventory();else if(view==='incidents')renderIncidents();else renderPlaceholder(view)}
async function renderDashboard(){document.querySelector('#app').innerHTML='<div class="loading">Cargando dashboard...</div>';try{const response=await api('listDevices');if(response.status!=='ok')throw new Error(response.message||'Error de API');const devices=response.data||[],counts=devices.reduce((a,x)=>(a[x.estado]=(a[x.estado]||0)+1,a),{});document.querySelector('#connection-status').textContent=window.LDU_CONFIG.DEMO_MODE?'Demo local':'API conectada';document.querySelector('#app').innerHTML=`<div class="cards">${metric('Total de dispositivos',devices.length)}${metric('Activos',counts.Activo||0)}${metric('Dañados',counts.Dañado||0)}${metric('Perdidos',counts.Perdido||0)}${metric('En reparación',counts['En Reparación']||0)}${metric('Pendientes de devolución',counts['Pendiente Devolución']||0)}${metric('Devueltos',counts.Devuelto||0)}${metric('Dados de baja',counts.Baja||0)}</div><section class="section"><div class="section-head"><h2>Resumen del sistema</h2></div><div class="section-body"><p>El dashboard está conectado a <strong>LDU_Dispositivos</strong>. Los indicadores se actualizarán automáticamente cuando se registren equipos y movimientos.</p><button class="btn" onclick="navigate('inventory')">Abrir inventario</button></div></section>`}catch(error){document.querySelector('#connection-status').textContent='Error de conexión';document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>No se pudo cargar Dashboard</h2></div><div class="error">${esc(error.message)}</div><div class="section-body"><button class="btn" onclick="renderDashboard()">Reintentar</button></div></section>`}}
function renderPlaceholder(view){const title=navItems.find(x=>x[0]===view)?.[1]||'Módulo';document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>${esc(title)}</h2></div><div class="empty">Módulo preparado para la siguiente iteración.</div></section>`}
async function renderInventory(){document.querySelector('#app').innerHTML=`<div id="inventory-root" class="loading">Cargando inventario...</div>`;try{const response=await api('listDevices',state.filters);if(response.status!=='ok')throw new Error(response.message||'Error de API');state.devices=response.data||[];document.querySelector('#connection-status').textContent=window.LDU_CONFIG.DEMO_MODE?'Demo local':'API conectada';renderInventoryView()}catch(error){document.querySelector('#connection-status').textContent='Error de conexión';document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>No se pudo cargar Inventario LDU</h2></div><div class="error">${esc(error.message)}</div><div class="section-body"><button class="btn" onclick="renderInventory()">Reintentar</button></div></section>`}}
function renderInventoryView(){const d=state.devices;const counts=d.reduce((a,x)=>(a[x.estado]=(a[x.estado]||0)+1,a),{});document.querySelector('#app').innerHTML=`<div class="cards">${metric('Dispositivos visibles',d.length)}${metric('Activos',counts.Activo||0)}${metric('Con incidencia',(counts.Dañado||0)+(counts.Perdido||0))}${metric('Devueltos',counts.Devuelto||0)}</div><section class="section"><div class="section-head"><h2>Inventario LDU</h2><div><button class="btn" id="new-device">Nuevo dispositivo</button> <button class="btn" id="export-demo">Exportar</button></div></div><div class="section-body"><div class="toolbar"><input id="device-search" class="input" placeholder="Buscar IMEI, modelo, responsable..." value="${esc(state.filters.query)}"><select id="device-state" class="select"><option value="">Todos los estados</option>${['Activo','Dañado','En Reparación','Perdido','Baja','Pendiente Devolución','Devuelto'].map(s=>`<option ${state.filters.estado===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn secondary" id="clear-filters">Limpiar filtros</button></div></div><div class="table-wrap"><table><thead><tr><th>IMEI</th><th>Modelo</th><th>Responsable</th><th>Supervisor</th><th>Zona</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${d.length?d.map(deviceRow).join(''):`<tr><td colspan="7" class="empty">Sin resultados</td></tr>`}</tbody></table></div></section>`;document.querySelector('#device-search').addEventListener('input',e=>{state.filters.query=e.target.value;renderInventory()});document.querySelector('#device-state').addEventListener('change',e=>{state.filters.estado=e.target.value;renderInventory()});document.querySelector('#clear-filters').addEventListener('click',()=>{state.filters={query:'',estado:''};renderInventory()});document.querySelector('#new-device').addEventListener('click',openDeviceForm);document.querySelector('#export-demo').addEventListener('click',()=>alert('La exportación se habilitará en la siguiente iteración.'));document.querySelectorAll('[data-device]').forEach(b=>b.addEventListener('click',()=>showDetail(d.find(x=>x.device_id===b.dataset.device))))}
function openDeviceForm(){openDeviceFormFull()}
function openDeviceFormFull(){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card"><div class="section-head"><h2>Nuevo dispositivo</h2><button class="btn secondary" id="close-device">Cerrar</button></div><form id="device-form" class="section-body"><label>IMEI *<input class="input" name="imei" required minlength="15" maxlength="17" inputmode="numeric"></label><label>Marca<input class="input" name="marca" value="VIVO"></label><label>Modelo *<input class="input" name="modelo" required></label><label>N° Línea<input class="input" name="n_linea"></label><label>Responsable<input class="input" name="responsable"></label><label>DNI<input class="input" name="dni"></label><label>Cargo<input class="input" name="cargo"></label><label>Tipo<input class="input" name="tipo"></label><label>Supervisor<input class="input" name="supervisor"></label><label>Zona<input class="input" name="zona"></label><label>Cuenta<input class="input" name="cuenta"></label><label>Departamento<input class="input" name="departamento"></label><label>City<input class="input" name="city"></label><label>Canal<input class="input" name="canal"></label><label>Tienda<input class="input" name="tienda"></label><label>Tipo Uso<input class="input" name="tipo_uso"></label><label>F. Asignación<input class="input" name="fecha_asignacion" type="date"></label><label>Monto S/ *<input class="input" name="monto" type="number" min="0.01" step="0.01" required></label><label>Estado<select class="select" name="estado"><option>Activo</option><option>Daño</option><option>Perdido</option><option>Devuelto</option><option>Baja</option></select></label><label>Observaciones<textarea class="input" name="observaciones"></textarea></label><button class="btn" type="submit">Guardar dispositivo</button><div id="device-form-message"></div></form></aside>`;document.body.appendChild(drawer);drawer.querySelector('#close-device').addEventListener('click',()=>drawer.remove());drawer.querySelector('#device-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,msg=drawer.querySelector('#device-form-message');const device=Object.fromEntries(new FormData(form).entries());msg.textContent='Guardando...';const result=await api('createDevice',{device,userId:'web-user'});if(result.status==='ok'){drawer.remove();await renderInventory()}else{msg.textContent=result.message||'No se pudo guardar el dispositivo.'}})}
function deviceRow(d){return `<tr><td>${esc(d.imei)}</td><td>${esc(d.modelo)}</td><td>${esc(d.responsable||'Sin responsable')}</td><td>${esc(d.supervisor||'—')}</td><td>${esc(d.zona||'—')}</td><td>${badge(d.estado)}</td><td><button class="btn secondary" data-device="${esc(d.device_id)}">Ver detalle</button></td></tr>`}
function showDetail(d){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card"><div class="section-head"><h2>Detalle del dispositivo</h2><button class="btn secondary" id="close-detail">Cerrar</button></div>${Object.entries(d).map(([k,v])=>`<div class="detail-row"><b>${esc(k.replaceAll('_',' '))}</b>${esc(v||'—')}</div>`).join('')}</aside>`;document.body.appendChild(drawer);drawer.querySelector('#close-detail').addEventListener('click',()=>drawer.remove())}
async function renderIncidents(){document.querySelector('#app').innerHTML='<div class="loading">Cargando incidencias...</div>';const response=await api('listIncidents');const incidents=response.data||[];const byType=incidents.reduce((a,x)=>(a[x.tipo]=(a[x.tipo]||0)+1,a),{});document.querySelector('#app').innerHTML=`<div class="cards">${metric('Total incidencias',incidents.length)}${metric('Daños',byType.Daño||0)}${metric('Pérdidas',byType.Pérdida||0)}${metric('Robos',byType.Robo||0)}</div><section class="section"><div class="section-head"><h2>Registrar incidencia</h2></div><div class="section-body"><form id="incident-form" class="toolbar"><input class="input" name="imei_original" placeholder="IMEI original" required><select class="select" name="tipo"><option>Daño</option><option>Pérdida</option><option>Robo</option><option>Otro</option></select><input class="input" name="nombre" placeholder="Colaborador"><input class="input" name="modelo" placeholder="Modelo"><input class="input" name="valor" type="number" min="0" step="0.01" placeholder="Valor S/"><button class="btn">Guardar incidencia</button></form></div></section><section class="section"><div class="section-head"><h2>Incidencias registradas</h2></div><div class="table-wrap"><table><thead><tr><th>IMEI</th><th>Tipo</th><th>Colaborador</th><th>Modelo</th><th>Valor</th><th>Estado</th></tr></thead><tbody>${incidents.length?incidents.map(i=>`<tr><td>${esc(i.imei_original)}</td><td>${badge(i.tipo==='Daño'?'Dañado':i.tipo)}</td><td>${esc(i.nombre||'—')}</td><td>${esc(i.modelo||'—')}</td><td>S/ ${esc(i.valor||0)}</td><td>${esc(i.estado_proceso||'Pendiente')}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">Sin incidencias</td></tr>`}</tbody></table></div></section>`;document.querySelector('#incident-form').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target),incident=Object.fromEntries(form.entries());const result=await api('createIncident',{incident,userId:'demo-user'});if(result.status==='ok')renderIncidents();else alert(result.message)})}

async function renderDashboard(){document.querySelector('#app').innerHTML='<div class="loading">Cargando dashboard...</div>';try{const [deviceResponse,incidentResponse]=await Promise.all([api('listDevices'),api('listIncidents')]);if(deviceResponse.status!=='ok')throw new Error(deviceResponse.message||'Error de API');const devices=deviceResponse.data||[],incidents=incidentResponse.data||[];document.querySelector('#connection-status').textContent=window.LDU_CONFIG.DEMO_MODE?'Demo local':'API conectada';const c=devices.reduce((a,d)=>(a[d.estado]=(a[d.estado]||0)+1,a),{}),stock=devices.length,inventory=devices.filter(d=>d.estado!=='Devuelto'&&d.estado!=='Baja').length;document.querySelector('#app').innerHTML=`<div class="cards dashboard-overview">${metric('Stock',stock)}${metric('En inventario',inventory)}${metric('Activos',c.Activo||0)}${metric('Almacén',c.Almacén||0)}${metric('Dañados',c.Dañado||0)}${metric('Reparación',c['En Reparación']||0)}${metric('Perdidos',c.Perdido||0)}${metric('Baja',c.Baja||0)}${metric('P. Dev',c['Pendiente Devolución']||0)}${metric('Devueltos',c.Devuelto||0)}${metric('Faltante',Math.max(0,stock-inventory))}</div>${dashboardStateSection('📈 Estados — 📱 Inventario LDU',devices,'blue')}${dashboardStateSection('📈 Estados — 🟦 Modelos Antiguos A',devices.filter(d=>/^(V50|Y04|Y19S|Y29S|Y39)/i.test(d.modelo||'')),'a')}${dashboardStateSection('📈 Estados — 🟧 Modelos Antiguos B',devices.filter(d=>/^(V21|V25|V30|V40|Y03|Y16|Y17|Y18|Y22S|Y27|Y28S|Y35|Y36|Y55)/i.test(d.modelo||'')),'b')}${dashboardIncidentSection(incidents)}${dashboardDepartments(devices)}${dashboardModelSummary(devices)}<div class="dashboard-bottom"><section class="section"><div class="section-head"><h2>📱 Últimos dispositivos</h2></div>${dashboardTable(devices.slice(-5).reverse(),['imei','modelo','responsable','estado'])}</section><section class="section"><div class="section-head"><h2>⚠️ Incidencias recientes</h2></div>${dashboardTable(incidents.slice(-5).reverse(),['imei_original','tipo','nombre','estado_proceso'])}</section></div>`}catch(error){document.querySelector('#connection-status').textContent='Error de conexión';document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>No se pudo cargar Dashboard</h2></div><div class="error">${esc(error.message)}</div><div class="section-body"><button class="btn" onclick="renderDashboard()">Reintentar</button></div></section>`}}
function dashboardStateSection(title,rows,color){const c=rows.reduce((a,d)=>(a[d.estado]=(a[d.estado]||0)+1,a),{});return `<section class="section dashboard-module ${color}"><div class="section-head"><h2>${title}</h2><button class="btn secondary" onclick="navigate('inventory')">Ver todo</button></div><div class="cards compact">${metric('Stock',rows.length)}${metric('En inventario',rows.filter(d=>d.estado!=='Devuelto').length)}${metric('Activos',c.Activo||0)}${metric('Almacén',c.Almacén||0)}${metric('Dañados',c.Dañado||0)}${metric('Reparac.',c['En Reparación']||0)}${metric('Perdidos',c.Perdido||0)}${metric('Baja',c.Baja||0)}${metric('P. Dev',c['Pendiente Devolución']||0)}${metric('Devuelto',c.Devuelto||0)}</div></section>`}
function dashboardIncidentSection(rows){const c=rows.reduce((a,i)=>(a[i.tipo]=(a[i.tipo]||0)+1,a),{});return `<section class="section"><div class="section-head"><h2>⚠️ Incidencias</h2><button class="btn secondary" onclick="navigate('incidents')">Ver todo</button></div><div class="cards compact">${metric('Total',rows.length)}${metric('Daños',c.Daño||0)}${metric('Pérdidas',c.Pérdida||0)}${metric('Robos',c.Robo||0)}${metric('Otros',c.Otro||0)}${metric('Reposición',c.Reposición||0)}${metric('Devolución',c.Devolución||0)}${metric('Valor total','S/ '+rows.reduce((n,i)=>n+Number(i.valor||0),0).toFixed(2))}</div></section>`}
function dashboardDepartments(rows){const c=rows.reduce((a,d)=>{const k=d.departamento||'Sin departamento';a[k]=(a[k]||0)+1;return a},{});return `<section class="section"><div class="section-head"><h2>📍 Mapeo de LDU por Departamento</h2></div>${dashboardTable(Object.entries(c).sort((a,b)=>b[1]-a[1]).map(x=>({departamento:x[0],equipos:x[1]})),['departamento','equipos'])}</section>`}
function dashboardModelSummary(rows){const c=rows.reduce((a,d)=>{const k=d.modelo||'Sin modelo';a[k]=(a[k]||0)+1;return a},{});return `<section class="section"><div class="section-head"><h2>📦 Resumen de Stock por Modelo</h2><button class="btn secondary" onclick="navigate('inventory')">Ver inventario</button></div>${dashboardTable(Object.entries(c).sort((a,b)=>b[1]-a[1]).map(x=>({modelo:x[0],stock:x[1]})),['modelo','stock'])}</section>`}
function dashboardTable(rows,fields){return `<div class="table-wrap"><table><thead><tr>${fields.map(f=>`<th>${esc(f.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${fields.map(f=>`<td>${esc(r[f]||'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${fields.length}" class="empty">Sin datos</td></tr>`}</tbody></table></div>`}

async function renderDashboard(){document.querySelector('#app').innerHTML='<div class="loading">⏳ Cargando dashboard...</div>';try{const [dr,ir]=await Promise.all([api('listDevices'),api('listIncidents')]);const devices=dr.data||[],incidents=ir.data||[];document.querySelector('#connection-status').textContent=window.LDU_CONFIG.DEMO_MODE?'Demo local':'API conectada';const stats=dashboardStats(devices),byType=incidents.reduce((a,x)=>(a[x.tipo]=(a[x.tipo]||0)+1,a),{});document.querySelector('#app').innerHTML=`<div class="dashboard-toolbar"><button class="btn" onclick="renderDashboard()">🔄 Actualizar</button><button class="btn secondary" onclick="dashboardImport()">📥 Importar Excel</button><button class="btn secondary" onclick="dashboardExport()">📤 Exportar Excel</button></div><div class="cards dashboard-overview">${dashboardMetric('📦 Stock',stats.stock)}${dashboardMetric('📋 En inventario',stats.enInventario)}${dashboardMetric('✅ Activos',stats.activos)}${dashboardMetric('🏬 Almacén',stats.almacen)}${dashboardMetric('🛠️ Dañados',stats.danados)}${dashboardMetric('🔧 Reparación',stats.reparacion)}${dashboardMetric('🔎 Perdidos',stats.perdidos)}${dashboardMetric('⛔ Baja',stats.baja)}${dashboardMetric('📦 P. Dev',stats.pdev)}${dashboardMetric('↩️ Devueltos',stats.devuelto)}${dashboardMetric('⚠️ Faltante',stats.faltante)}${dashboardMetric('↩️ Total equipos devueltos',stats.devuelto)}${dashboardMetric('🏬 Total equipos en almacén',stats.almacen)}${dashboardMetric('📱 Total IMEI en inventario',stats.enInventario)}${dashboardMetric('🚫 IMEI fuera de inventario',stats.fueraInventario)}${dashboardMetric('📦 Total de stock',stats.stock)}${dashboardMetric('📵 IMEI no vivo',stats.imeiNoVivo)}</div>${stockSummaryDashboard(devices)}<section class="section"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="dashboardExport()">📤 Excel</button><button class="btn secondary" onclick="navigate('incidents')">Ver todo →</button></div></div><div class="cards compact">${dashboardMetric('💥 Daños',byType.Daño||0)}${dashboardMetric('🔍 Pérdidas',byType.Pérdida||0)}${dashboardMetric('🕵️ Robos',byType.Robo||0)}${dashboardMetric('📌 Otros',byType.Otro||0)}${dashboardMetric('🔁 Reposición',byType.Reposición||0)}${dashboardMetric('↩️ Devolución',byType.Devolución||0)}${dashboardMetric('⏳ Pendiente',incidents.filter(x=>(x.estado_proceso||'Pendiente')==='Pendiente').length)}${dashboardMetric('🔄 En curso',incidents.filter(x=>x.estado_proceso==='En Curso').length)}${dashboardMetric('💰 Valor total','S/ '+incidents.reduce((n,x)=>n+Number(x.valor||0),0).toFixed(2))}</div></section>${dashboardMapSection(devices)}<div class="dashboard-bottom"><section class="section"><div class="section-head"><h2>📱 Últimos dispositivos</h2></div>${dashboardTable(devices.slice(-5).reverse(),['imei','modelo','responsable','estado'])}</section><section class="section"><div class="section-head"><h2>⚠️ Incidencias recientes</h2></div>${dashboardTable(incidents.slice(-5).reverse(),['imei_original','tipo','nombre','estado_proceso'])}</section></div>`}catch(e){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>❌ No se pudo cargar el Dashboard</h2></div><div class="error">${esc(e.message)}</div><div class="section-body"><button class="btn" onclick="renderDashboard()">Reintentar</button></div></section>`}}
function dashboardMetric(label,value){return `<article class="metric"><strong>${esc(value)}</strong><span>${esc(label)}</span></article>`}
function dashboardStats(rows){const c=rows.reduce((a,d)=>(a[d.estado]=(a[d.estado]||0)+1,a),{}),stock=rows.length,enInventario=rows.filter(d=>!['Devuelto','Baja'].includes(d.estado)).length;return{stock,enInventario,activos:c.Activo||0,almacen:c.Almacén||0,danados:c.Dañado||0,reparacion:c['En Reparación']||0,perdidos:c.Perdido||0,baja:c.Baja||0,pdev:c['Pendiente Devolución']||0,devuelto:c.Devuelto||0,faltante:Math.max(0,stock-enInventario),fueraInventario:rows.filter(d=>['Devuelto','Baja'].includes(d.estado)).length,imeiNoVivo:0}}
function stockSummaryDashboard(rows){const groups=[['✅ Inventario LDU',rows.filter(d=>!['A','B'].includes(String(d.grupo||'').toUpperCase())),'inventory'],['🟦 Modelos Antiguos A',rows.filter(d=>String(d.grupo||'').toUpperCase()==='A'),'a'],['🟧 Modelos Antiguos B',rows.filter(d=>String(d.grupo||'').toUpperCase()==='B'),'b']];return `<section class="section stock-summary"><div class="section-head"><h2>📦 Resumen de Stock por Modelo</h2><button class="btn secondary" onclick="renderDashboard()">🔄 Actualizar</button></div>${groups.map(([title,list,key])=>stockGroup(title,list,key)).join('')}</section>`}
function stockGroup(title,rows,key){const models={};rows.forEach(d=>{const m=d.modelo||'Sin modelo';models[m]||(models[m]=[]);models[m].push(d)});const data=Object.keys(models).map(m=>stockModelRow(m,models[m]));return `<div class="stock-group ${key}"><div class="stock-group-head"><h3>${title}</h3><div><button class="btn secondary" onclick="navigate('inventory')">📋 ${key==='inventory'?'Ver Inventario':key==='a'?'Ver Mod. A':'Ver Mod. B'}</button><button class="btn secondary" onclick="dashboardExport()">📄 Excel</button></div></div>${dashboardTable(data,['modelo','stock','en_inv','activos','almacen','danados','reparacion','perdidos','baja','pdev','devuelto','monto','faltante'])}</div>`}
function stockModelRow(model,rows){const c=dashboardStats(rows);return{modelo,stock:c.stock,en_inv:c.enInventario,activos:c.activos,almacen:c.almacen,danados:c.danados,reparacion:c.reparacion,perdidos:c.perdidos,baja:c.baja,pdev:c.pdev,devuelto:c.devuelto,monto:'S/ '+rows.reduce((n,x)=>n+Number(x.monto||0),0).toFixed(2),faltante:c.faltante}}
function dashboardMapSection(rows){const accounts=['CLARO','ENTEL','OPEN MARKET','RETAIL','VIVO'],accountCounts=accounts.map(a=>({name:a,count:rows.filter(d=>String(d.cuenta||'').toUpperCase()===a).length})),dep={};rows.forEach(d=>{const k=d.departamento||'Sin departamento';dep[k]=(dep[k]||0)+1});return `<section class="section dashboard-map"><div class="section-head"><h2>📍 Mapeo de LDU por Departamento</h2><div><select class="select"><option>📍 Departamentos</option></select><select class="select"><option>🏙️ Ciudades</option></select><select class="select"><option>🏢 Cuentas</option></select></div></div><div class="account-cards">${accountCounts.map(a=>`<article class="account-card"><strong>${esc(a.name)}</strong><b>${a.count}</b><span>equipos</span></article>`).join('')}</div><div class="peru-map"><div class="peru-shape">🇵🇪<strong>Mapa de Perú</strong><small>Se actualizará por departamento al cargar dispositivos.</small></div>${dashboardTable(Object.entries(dep).sort((a,b)=>b[1]-a[1]).map(x=>({departamento:x[0],equipos:x[1]})),['departamento','equipos'])}</div></section>`}
function dashboardImport(){alert('El importador Excel se habilitará en el módulo Importar. Por ahora el Dashboard está conectado a LDU_Dispositivos.')}
function dashboardExport(){const rows=window.__LDU_LAST_DEVICES||[];if(!rows.length){alert('No hay datos para exportar.');return}const csv=Object.keys(rows[0]).join(',')+'\n'+rows.map(r=>Object.values(r).map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='dashboard-ldu.csv';a.click()}
async function dashboardExport(){const response=await api('listDevices');const rows=response.data||[];if(!rows.length){alert('No hay datos para exportar.');return}const csv=Object.keys(rows[0]).join(',')+'\n'+rows.map(r=>Object.values(r).map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='dashboard-ldu.csv';a.click()}

async function renderDashboard(){document.querySelector('#app').innerHTML='<div class="loading">⏳ Cargando dashboard...</div>';try{const [dr,ir]=await Promise.all([api('listDevices'),api('listIncidents')]);const devices=dr.data||[],incidents=ir.data||[];window.__LDU_LAST_DEVICES=devices;const s=dashboardStats(devices),types=incidents.reduce((a,x)=>(a[x.tipo]=(a[x.tipo]||0)+1,a),{});document.querySelector('#connection-status').textContent=window.LDU_CONFIG.DEMO_MODE?'Demo local':'API conectada';document.querySelector('#app').innerHTML=`<div class="dashboard-toolbar"><button class="btn" onclick="renderDashboard()">🔄 Actualizar</button><button class="btn secondary" onclick="dashboardImport()">📥 Importar Excel</button><button class="btn secondary" onclick="dashboardExport()">📤 Exportar Excel</button></div><div class="cards dashboard-overview">${dashboardMetric('📦 TOTAL STOCK',s.stock)}${dashboardMetric('📋 TOTAL EN INVENTARIO',s.enInventario)}${dashboardMetric('✅ TOTAL ACTIVOS',s.activos)}${dashboardMetric('🏬 TOTAL EN ALMACÉN',s.almacen)}${dashboardMetric('🛠️ TOTAL DAÑADOS',s.danados)}${dashboardMetric('🔧 TOTAL EN REPARACIÓN',s.reparacion)}${dashboardMetric('🔎 TOTAL PERDIDOS',s.perdidos)}${dashboardMetric('⛔ TOTAL EN BAJA',s.baja)}${dashboardMetric('📦 TOTAL P. DEV',s.pdev)}${dashboardMetric('↩️ TOTAL DEVUELTOS',s.devuelto)}${dashboardMetric('⚠️ TOTAL FALTANTE',s.faltante)}${dashboardMetric('↩️ TOTAL EQUIPOS DEVUELTOS',s.devuelto)}${dashboardMetric('🏬 TOTAL EQUIPOS EN ALMACÉN',s.almacen)}${dashboardMetric('📱 TOTAL IMEI EN INVENTARIO',s.enInventario)}${dashboardMetric('🚫 TOTAL IMEI FUERA DE INVENTARIO',s.fueraInventario)}${dashboardMetric('📦 TOTAL DE STOCK',s.stock)}${dashboardMetric('📵 IMEI NO VIVO',s.imeiNoVivo)}</div>${dashboardStateSection('📈 Estados — 📱 Inventario LDU',devices,'inventory')}${dashboardStateSection('📈 Estados — 🟦 Modelos Antiguos A',devices.filter(d=>String(d.grupo||'').toUpperCase()==='A'),'a')}${dashboardStateSection('📈 Estados — 🟧 Modelos Antiguos B',devices.filter(d=>String(d.grupo||'').toUpperCase()==='B'),'b')}<section class="section dashboard-incidents"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="dashboardExport()">📄 Excel</button><button class="btn secondary" onclick="navigate('incidents')">Ver todo →</button></div></div><div class="cards compact">${dashboardMetric('💥 Daños',types.Daño||0)}${dashboardMetric('🔍 Pérdidas',types.Pérdida||0)}${dashboardMetric('🕵️ Robos',types.Robo||0)}${dashboardMetric('📌 Otros',types.Otro||0)}${dashboardMetric('🔁 Reposición',types.Reposición||0)}${dashboardMetric('↩️ Devolución',types.Devolución||0)}${dashboardMetric('⏳ Pendiente',incidents.filter(x=>(x.estado_proceso||'Pendiente')==='Pendiente').length)}${dashboardMetric('🔄 En curso',incidents.filter(x=>x.estado_proceso==='En Curso').length)}${dashboardMetric('💰 Valor total','S/ '+incidents.reduce((n,x)=>n+Number(x.valor||0),0).toFixed(2))}</div></section>${dashboardMapSection(devices)}${stockSummaryDashboard(devices)}<div class="dashboard-bottom"><section class="section"><div class="section-head"><h2>📱 Últimos dispositivos</h2></div>${dashboardTable(devices.slice(-5).reverse(),['imei','modelo','responsable','estado'])}</section><section class="section"><div class="section-head"><h2>⚠️ Incidencias recientes</h2></div>${dashboardTable(incidents.slice(-5).reverse(),['imei_original','tipo','nombre','estado_proceso'])}</section></div>`}catch(e){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>❌ No se pudo cargar el Dashboard</h2></div><div class="error">${esc(e.message)}</div><div class="section-body"><button class="btn" onclick="renderDashboard()">Reintentar</button></div></section>`}}
function dashboardStateSection(title,rows,key){const c=dashboardStats(rows);return `<section class="section dashboard-module ${key}"><div class="section-head"><h2>${title}</h2><div><button class="btn secondary" onclick="dashboardExport()">📄 Excel</button><button class="btn secondary" onclick="navigate('inventory')">Ver todo →</button></div></div><div class="cards compact">${dashboardMetric('📦 Total',c.stock)}${dashboardMetric('✅ Activos',c.activos)}${dashboardMetric('⚠️ Dañados',c.danados)}${dashboardMetric('🔧 Reparación',c.reparacion)}${dashboardMetric('🔎 Perdidos',c.perdidos)}${dashboardMetric('⛔ Baja',c.baja)}${dashboardMetric('📦 P. Dev',c.pdev)}${dashboardMetric('↩️ Devueltos',c.devuelto)}${dashboardMetric('🏬 Almacén',c.almacen)}${dashboardMetric('👤 Sin responsable',rows.filter(d=>!d.responsable).length)}</div></section>`}
function dashboardMapSection(rows){const accounts=['CLARO','ENTEL','OPEN MARKET','RETAIL','VIVO'],dep={};rows.forEach(d=>{const k=d.departamento||'Sin departamento';dep[k]=(dep[k]||0)+1});return `<section class="section dashboard-map"><div class="section-head"><h2>📍 Mapeo de LDU por Departamento</h2><div class="map-filters"><select class="select"><option>📍 Departamentos</option></select><select class="select"><option>🏙️ Ciudades</option></select><select class="select"><option>🏢 Cuentas</option></select></div></div><div class="account-cards">${accounts.map(a=>`<article class="account-card account-${a.toLowerCase().replaceAll(' ','-')}"><strong>${a}</strong><b>${rows.filter(d=>String(d.cuenta||'').toUpperCase()===a).length}</b><span>equipos</span></article>`).join('')}</div><div class="map-content"><div class="peru-map-visual"><div class="peru-outline">🇵🇪</div><strong>Mapa de Perú</strong><small>Distribución por departamento</small></div>${dashboardTable(Object.entries(dep).sort((a,b)=>b[1]-a[1]).map(x=>({departamento:x[0],equipos:x[1]})),['departamento','equipos'])}</div></section>`}
function stockSummaryDashboard(rows){return `<section class="section stock-summary"><div class="section-head"><h2>📦 Resumen de Stock por Modelo</h2><button class="btn secondary" onclick="renderDashboard()">🔄 Actualizar</button></div>${stockGroup('✅ Inventario LDU',rows,'inventory')}${stockGroup('🟦 Modelos Antiguos A',rows.filter(d=>String(d.grupo||'').toUpperCase()==='A'),'a')}${stockGroup('🟧 Modelos Antiguos B',rows.filter(d=>String(d.grupo||'').toUpperCase()==='B'),'b')}</section>`}
function stockGroup(title,rows,key){const groups={};rows.forEach(d=>{const m=d.modelo||'Sin modelo';groups[m]||(groups[m]=[]);groups[m].push(d)});const data=Object.keys(groups).map(m=>stockModelRow(m,groups[m]));const headers=['Modelo','Stock','En Inv.','Activos','Almacén','Dañados','Reparac.','Perdidos','Baja','P.Dev','Devuelto','Monto S/','Faltante'];return `<div class="stock-group ${key}"><div class="stock-group-head"><h3>${title}</h3><div><button class="btn secondary" onclick="navigate('inventory')">📋 ${key==='inventory'?'Ver Inventario':key==='a'?'Ver Mod. A':'Ver Mod. B'}</button><button class="btn secondary" onclick="dashboardExport()">📄 Excel</button></div></div><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${data.length?data.map(r=>`<tr><td>${esc(r.modelo)}</td><td>${r.stock}</td><td>${r.en_inv}</td><td>${r.activos}</td><td>${r.almacen}</td><td>${r.danados}</td><td>${r.reparacion}</td><td>${r.perdidos}</td><td>${r.baja}</td><td>${r.pdev}</td><td>${r.devuelto}</td><td>${esc(r.monto)}</td><td>${r.faltante}</td></tr>`).join(''):`<tr><td colspan="13" class="empty">Sin datos</td></tr>`}</tbody></table></div></div>`}

const LDU_NAV_ITEMS=[{group:'Principal',items:[['dashboard','🏠','Dashboard']]},{group:'Módulos',items:[['inventory','📱','Inventario LDU'],['incidents','⚠️','Incidencias'],['stock','📦','Stock'],['modelA','🟦','Modelos Ant. A'],['modelB','🟧','Modelos Ant. B']]},{group:'Herramientas',items:[['search','🔍','Buscador'],['history','📋','Historial IMEI'],['notifications','🔔','Notificaciones'],['delete','🗑️','Eliminar'],['import','📥','Importar'],['stale','⏱️','IMEIs sin Actualizar'],['users','👥','Usuarios'],['settings','⚙️','Configuración']]}];
function allNavItems(){return LDU_NAV_ITEMS.flatMap(g=>g.items)}
function renderNav(){document.querySelector('#main-nav').innerHTML=LDU_NAV_ITEMS.map(g=>`<div class="nav-group">${g.group}</div>${g.items.map(([id,icon,label])=>`<button class="nav-item" data-view="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}`).join('');document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)))}
function navigate(view){state.view=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const item=allNavItems().find(x=>x[0]===view);document.querySelector('#page-title').textContent=item?item[2]:'Sistema LDU';if(view==='dashboard')renderDashboard();else if(view==='inventory')renderInventory();else if(view==='incidents')renderIncidents();else renderPlaceholder(view)}
document.addEventListener('DOMContentLoaded',()=>{const topbar=document.querySelector('.topbar');if(topbar&&!topbar.querySelector('.global-actions')){const actions=document.createElement('div');actions.className='global-actions';actions.innerHTML='<button class="top-action" onclick="renderDashboard()">🔄</button><button class="top-action" onclick="dashboardExport()">📄 Excel</button><button class="top-action primary" onclick="navigate(\'inventory\')">＋ Dispositivo</button>';topbar.appendChild(actions)}});
/* LDU module configuration override */
const LDU_GROUP_A=['V50','V50 LITE','V50LITE','Y19S','Y39','Y29S','Y04'];
const LDU_GROUP_B=['V40 SE','V40SE','V30 SE','V30SE','V25','V25E','Y36','Y28S','Y03','Y17S','Y18','Y53S','Y55','Y27','V21','Y16','Y17','Y35','Y22S'];
const LDU_TABLE_COLUMNS=[['imei','IMEI'],['marca','Marca'],['modelo','Modelo'],['n_linea','N° Línea'],['responsable','Responsable'],['dni','DNI'],['cargo','Cargo'],['tipo','Tipo'],['supervisor','Supervisor'],['zona','Zona'],['cuenta','Cuenta'],['departamento','Departamento'],['city','City'],['canal','Canal'],['tienda','Tienda'],['tipo_uso','Tipo de Uso'],['fecha_asignacion','F. Asignación'],['monto','Monto S/'],['estado','Estado']];
function lduModelKey(value){return String(value||'').toUpperCase().replace(/\s+/g,' ').trim()}
function lduGroupFor(model){const key=lduModelKey(model);if(LDU_GROUP_A.includes(key))return 'A';if(LDU_GROUP_B.includes(key))return 'B';return 'INVENTARIO'}
function lduRowsForGroup(rows,group){return rows.filter(row=>group==='inventory'?lduGroupFor(row.modelo)==='INVENTARIO':lduGroupFor(row.modelo)===group)}
function lduDistinct(rows,key){return [...new Set(rows.map(row=>String(row[key]||'').trim()).filter(Boolean))]}
function lduMatches(row,filters){const hay=[row.imei,row.marca,row.modelo,row.responsable,row.dni,row.supervisor,row.zona,row.cuenta,row.estado].join(' ').toLowerCase();return (!filters.query||hay.includes(filters.query.toLowerCase()))&&(!filters.supervisor||row.supervisor===filters.supervisor)&&(!filters.zona||row.zona===filters.zona)&&(!filters.cuenta||row.cuenta===filters.cuenta)&&(!filters.modelo||row.modelo===filters.modelo)&&(!filters.tipo_uso||row.tipo_uso===filters.tipo_uso)&&(!filters.estado||row.estado===filters.estado)}
function lduStateCards(rows){const s=dashboardStats(rows);return [['📦 Total',s.stock],['📋 En inventario',s.enInventario],['✅ Activos',s.activos],['🏬 Almacén',s.almacen],['🛠️ Dañados',s.danados],['🔧 Reparación',s.reparacion],['🔎 Perdidos',s.perdidos],['⛔ Baja',s.baja],['📦 Pendiente de Devolución',s.pdev],['↩️ Devueltos',s.devuelto],['⚠️ Faltante',s.faltante],['📵 IMEI no vivo',s.imeiNoVivo]].map(([label,value])=>dashboardMetric(label,value)).join('')}
function lduModuleTitle(group){return group==='inventory'?'📱 Inventario LDU':group==='A'?'🟦 Modelos Ant. A':'🟧 Modelos Ant. B'}
function lduSelect(name,label,values,current){return `<label class="filter-field"><span>${label}</span><select id="${name}" class="select"><option value="">Todos</option>${values.sort().map(v=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
async function renderModule(group){document.querySelector('#app').innerHTML='<div class="loading">⏳ Cargando '+esc(lduModuleTitle(group))+'...</div>';try{const response=await api('listDevices');if(response.status!=='ok')throw new Error(response.message||'Error de API');state.devices=response.data||[];state.moduleGroup=group;renderModuleView(group)}catch(error){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>No se pudo cargar ${esc(lduModuleTitle(group))}</h2></div><div class="error">${esc(error.message)}</div><div class="section-body"><button class="btn" onclick="renderModule('${group}')">Reintentar</button></div></section>`}}
function renderModuleView(group){const source=lduRowsForGroup(state.devices,group),filters=state.moduleFilters||{},rows=source.filter(row=>lduMatches(row,filters));const select=(id,label,key)=>lduSelect(id,label,lduDistinct(source,key),filters[key]);document.querySelector('#app').innerHTML=`<div class="module-cards cards compact">${lduStateCards(source)}</div><section class="section module-section"><div class="section-head"><h2>${lduModuleTitle(group)}</h2><div><button class="btn secondary" onclick="dashboardExportRows(window.__LDU_MODULE_ROWS||[],'${group}')">📄 Excel</button><button class="btn" onclick="openDeviceFormFull()">＋ Nuevo</button></div></div><div class="section-body"><div class="module-filters"><label class="filter-field search-field"><span>Buscar</span><input id="module-query" class="input" placeholder="IMEI, modelo, responsable..." value="${esc(filters.query||'')}"></label>${select('module-supervisor','Supervisor','supervisor')}${select('module-zona','Zona','zona')}${select('module-cuenta','Cuenta','cuenta')}${select('module-modelo','Modelo','modelo')}${select('module-uso','Tipo de Uso','tipo_uso')}${select('module-estado','Estado','estado')}<button class="btn secondary" id="module-clear">Limpiar filtros</button></div></div><div class="table-wrap module-table"><table><thead><tr>${LDU_TABLE_COLUMNS.map(c=>`<th>${c[1]}</th>`).join('')}<th>Acc.</th></tr></thead><tbody>${rows.length?rows.map(lduDeviceRow).join(''):`<tr><td colspan="20" class="empty">Sin resultados</td></tr>`}</tbody></table></div></section>`;window.__LDU_MODULE_ROWS=rows;const update=()=>{state.moduleFilters={query:document.querySelector('#module-query').value,supervisor:document.querySelector('#module-supervisor').value,zona:document.querySelector('#module-zona').value,cuenta:document.querySelector('#module-cuenta').value,modelo:document.querySelector('#module-modelo').value,tipo_uso:document.querySelector('#module-uso').value,estado:document.querySelector('#module-estado').value};renderModuleView(group)};['module-query','module-supervisor','module-zona','module-cuenta','module-modelo','module-uso','module-estado'].forEach(id=>document.querySelector('#'+id).addEventListener(id==='module-query'?'input':'change',update));document.querySelector('#module-clear').addEventListener('click',()=>{state.moduleFilters={};renderModuleView(group)});document.querySelectorAll('[data-module-action]').forEach(button=>button.addEventListener('click',()=>lduAction(button.dataset.moduleAction,button.dataset.device)))}
function lduDeviceRow(row){return `<tr>${LDU_TABLE_COLUMNS.map(([key])=>`<td>${key==='estado'?badge(row[key]):esc(row[key]||'—')}</td>`).join('')}<td class="row-actions"><button title="Ver" data-module-action="view" data-device="${esc(row.device_id||row.imei)}">👁️</button><button title="Historial" data-module-action="history" data-device="${esc(row.device_id||row.imei)}">📜</button><button title="Editar" data-module-action="edit" data-device="${esc(row.device_id||row.imei)}">✎️</button><button title="Eliminar" data-module-action="delete" data-device="${esc(row.device_id||row.imei)}">✕</button></td></tr>`}
function lduAction(action,id){const row=(window.__LDU_MODULE_ROWS||[]).find(item=>String(item.device_id||item.imei)===String(id));if(!row)return;if(action==='view')showDetail(row);else if(action==='history')navigate('history');else if(action==='edit')openDeviceFormFull(row);else if(action==='delete')alert('La eliminación quedará registrada en el módulo Eliminar.')}
function dashboardExportRows(rows,name){if(!rows.length){alert('No hay datos para exportar.');return}const keys=Object.keys(rows[0]);const csv=keys.join(',')+'\n'+rows.map(row=>keys.map(key=>`"${String(row[key]??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`${name}-ldu.csv`;a.click()}
function lduField(label,name,placeholder='',type='text',value=''){return `<label><span>${label}</span><input class="input" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value||'')}"></label>`}
function lduSelectField(label,name,options,value=''){return `<label><span>${label}</span><select class="select" name="${name}"><option value="">Seleccionar...</option>${options.map(option=>`<option ${value===option?'selected':''}>${option}</option>`).join('')}</select></label>`}
function openDeviceFormFull(existing){const d=existing||{},drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card device-form-card"><div class="section-head"><h2>📱 ${existing?'Editar dispositivo':'Nuevo dispositivo'}</h2><button class="btn secondary" id="close-device">✕</button></div><form id="device-form" class="device-form"><h3>🪪 Identificación</h3><div class="form-grid">${lduField('IMEI *','imei','15-17 dígitos','text',d.imei)}${lduSelectField('Estado *','estado',['Activo','Dañado','En Reparación','Perdido','Baja','Pendiente Devolución','Devuelto','Almacén'],d.estado||'Activo')}${lduField('Marca','marca','VIVO','text',d.marca||'VIVO')}${lduField('Modelo *','modelo','Y36, V60 Lite...','text',d.modelo)}${lduField('Grupo detectado','grupo_detectado','Se calcula al guardar','text',lduGroupFor(d.modelo)==='INVENTARIO'?'Inventario LDU':`Modelos Ant. ${lduGroupFor(d.modelo)}`)}${lduField('N° Línea','n_linea','9 dígitos','text',d.n_linea)}${lduField('Monto S/ *','monto','','number',d.monto)}</div><h3>👤 Responsable</h3><div class="form-grid">${lduField('Nombre completo','responsable','Apellidos y Nombres','text',d.responsable)}${lduField('DNI','dni','','text',d.dni)}${lduField('Cargo','cargo','','text',d.cargo)}${lduSelectField('Tipo','tipo',['Fijo','Ruta','Supervisor','Training','GTM','Almacén'],d.tipo)}${lduField('Supervisor','supervisor','','text',d.supervisor)}</div><h3>📍 Ubicación</h3><div class="form-grid">${lduField('Zona','zona','','text',d.zona)}${lduField('Departamento','departamento','','text',d.departamento)}${lduField('City','city','','text',d.city)}${lduField('Cuenta','cuenta','','text',d.cuenta)}${lduField('Canal','canal','','text',d.canal)}${lduField('Tienda','tienda','','text',d.tienda)}</div><h3>📋 Asignación</h3><div class="form-grid">${lduSelectField('Tipo de Uso','tipo_uso',['Exhibición','Promotor','Red de Trabajo','Equipo en Mano','Custodia'],d.tipo_uso)}${lduField('F. Asignación','fecha_asignacion','','date',d.fecha_asignacion)}<label class="full-field"><span>Observaciones</span><textarea class="input" name="observaciones">${esc(d.observaciones||'')}</textarea></label></div><div class="form-actions"><button class="btn secondary" type="button" id="cancel-device">Cancelar</button><button class="btn" type="submit">💾 Guardar</button></div><div id="device-form-message"></div></form></aside>`;document.body.appendChild(drawer);const close=()=>drawer.remove();drawer.querySelector('#close-device').addEventListener('click',close);drawer.querySelector('#cancel-device').addEventListener('click',close);const model=drawer.querySelector('[name="modelo"]'),group=drawer.querySelector('[name="grupo_detectado"]');model.addEventListener('input',()=>{const g=lduGroupFor(model.value);group.value=g==='INVENTARIO'?'Inventario LDU':`Modelos Ant. ${g}`});drawer.querySelector('#device-form').addEventListener('submit',async event=>{event.preventDefault();const msg=drawer.querySelector('#device-form-message'),device=Object.fromEntries(new FormData(event.target).entries());delete device.grupo_detectado;msg.textContent='Guardando...';const result=await api('createDevice',{device,userId:'web-user'});if(result.status==='ok'){close();renderModule(state.moduleGroup||'inventory')}else msg.textContent=result.message||'No se pudo guardar el dispositivo.'})}
function navigate(view){state.view=view;document.querySelectorAll('.nav-item').forEach(button=>button.classList.toggle('active',button.dataset.view===view));const item=allNavItems().find(entry=>entry[0]===view);document.querySelector('#page-title').textContent=item?item[2]:'Sistema LDU';if(view==='dashboard')renderDashboard();else if(view==='inventory')renderModule('inventory');else if(view==='modelA')renderModule('A');else if(view==='modelB')renderModule('B');else if(view==='incidents')renderIncidents();else renderPlaceholder(view)}
function dashboardStats(rows){const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),c=rows.reduce((acc,row)=>{const key=normalize(row.estado);acc[key]=(acc[key]||0)+1;return acc},{}),stock=rows.length,enInventario=rows.filter(row=>!['devuelto','baja'].includes(normalize(row.estado))).length;return{stock,enInventario,activos:c.activo||0,almacen:c.almacen||0,danados:c.danado||0,reparacion:c['en reparacion']||0,perdidos:c.perdido||0,baja:c.baja||0,pdev:c['pendiente devolucion']||0,devuelto:c.devuelto||0,faltante:Math.max(0,stock-enInventario),fueraInventario:rows.filter(row=>['devuelto','baja'].includes(normalize(row.estado))).length,imeiNoVivo:0}}
function dashboardStats(rows){const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),c=rows.reduce((acc,row)=>{const key=normalize(row.estado);acc[key]=(acc[key]||0)+1;return acc},{}),stock=rows.length,enInventario=rows.filter(row=>!['devuelto','baja'].includes(normalize(row.estado))).length;return{stock,enInventario,activos:c.activo||0,almacen:c.almacen||0,danados:c.danado||0,reparacion:c['en reparacion']||0,perdidos:c.perdido||0,baja:c.baja||0,pdev:c['pendiente devolucion']||0,devuelto:c.devuelto||0,faltante:Math.max(0,stock-enInventario),fueraInventario:rows.filter(row=>['devuelto','baja'].includes(normalize(row.estado))).length,imeiNoVivo:0,valorTotal:rows.reduce((total,row)=>total+Number(row.monto||0),0)}}
function lduStateCards(rows){const s=dashboardStats(rows);return [['📦 Total',s.stock],['📋 En inventario',s.enInventario],['✅ Activos',s.activos],['🏬 Almacén',s.almacen],['🛠️ Dañados',s.danados],['🔧 Reparación',s.reparacion],['🔎 Perdidos',s.perdidos],['⛔ Baja',s.baja],['📦 Pendiente de Devolución',s.pdev],['↩️ Devueltos',s.devuelto],['⚠️ Faltante',s.faltante],['📵 IMEI no vivo',s.imeiNoVivo],['💰 Valor total','S/ '+s.valorTotal.toFixed(2)]].map(([label,value])=>dashboardMetric(label,value)).join('')}
function dashboardStateSection(title,rows,key){return `<section class="section dashboard-module ${key}"><div class="section-head"><h2>${title}</h2><div><button class="btn secondary" onclick="dashboardExportRows(${JSON.stringify(rows).replaceAll('"','&quot;')},'${key}')">📄 Excel</button><button class="btn secondary" onclick="navigate('${key==='inventory'?'inventory':key==='a'?'modelA':'modelB'}')">Ver todo →</button></div></div><div class="cards compact">${lduStateCards(rows)}</div></section>`}
function dashboardIncidentCards(rows){const norm=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),type=rows.reduce((acc,row)=>{const key=norm(row.tipo);acc[key]=(acc[key]||0)+1;return acc},{}),status=rows.reduce((acc,row)=>{const key=norm(row.estado_proceso||'pendiente');acc[key]=(acc[key]||0)+1;return acc},{});return [['📊 Total',rows.length],['⏳ Pendiente',status.pendiente||0],['🔄 En curso',status['en curso']||0],['💥 Dañados',type.dano||0],['🔎 Perdidos',type.perdida||0],['🕵️ Robados',type.robo||0],['📌 Otros',type.otro||0],['🔁 Reposición',type.reposicion||0],['↩️ Devolución',type.devolucion||0],['💰 Valor total','S/ '+rows.reduce((n,row)=>n+Number(row.valor||0),0).toFixed(2)]].map(([label,value])=>dashboardMetric(label,value)).join('')}
async function renderDashboard(){document.querySelector('#app').innerHTML='<div class="loading">⏳ Cargando dashboard...</div>';try{const [dr,ir]=await Promise.all([api('listDevices'),api('listIncidents')]),devices=dr.data||[],incidents=ir.data||[],s=dashboardStats(devices);window.__LDU_LAST_DEVICES=devices;document.querySelector('#connection-status').textContent=window.LDU_CONFIG.DEMO_MODE?'Demo local':'API conectada';document.querySelector('#app').innerHTML=`<div class="dashboard-toolbar"><button class="btn" onclick="renderDashboard()">🔄 Actualizar</button><button class="btn secondary" onclick="dashboardImport()">📥 Importar Excel</button><button class="btn secondary" onclick="dashboardExportRows(window.__LDU_LAST_DEVICES||[],'dashboard')">📤 Exportar Excel</button></div><div class="cards dashboard-overview">${dashboardMetric('📦 TOTAL STOCK',s.stock)}${dashboardMetric('📋 TOTAL EN INVENTARIO',s.enInventario)}${dashboardMetric('✅ TOTAL ACTIVOS',s.activos)}${dashboardMetric('🏬 TOTAL EN ALMACÉN',s.almacen)}${dashboardMetric('🛠️ TOTAL DAÑADOS',s.danados)}${dashboardMetric('🔧 TOTAL EN REPARACIÓN',s.reparacion)}${dashboardMetric('🔎 TOTAL PERDIDOS',s.perdidos)}${dashboardMetric('⛔ TOTAL EN BAJA',s.baja)}${dashboardMetric('📦 PENDIENTE DE DEVOLUCIÓN',s.pdev)}${dashboardMetric('↩️ TOTAL DEVUELTOS',s.devuelto)}${dashboardMetric('⚠️ TOTAL FALTANTE',s.faltante)}${dashboardMetric('↩️ TOTAL EQUIPOS DEVUELTOS',s.devuelto)}${dashboardMetric('🏬 TOTAL EQUIPOS EN ALMACÉN',s.almacen)}${dashboardMetric('🚫 TOTAL IMEI NO INVENTARIO',s.fueraInventario)}${dashboardMetric('📦 TOTAL DE STOCK',s.stock)}${dashboardMetric('📵 TOTAL IMEI NO VIVO',s.imeiNoVivo)}${dashboardMetric('💰 VALOR TOTAL','S/ '+s.valorTotal.toFixed(2))}</div>${dashboardStateSection('📈 Estados — 📱 Inventario LDU',lduRowsForGroup(devices,'inventory'),'inventory')}${dashboardStateSection('📈 Estados — 🟦 Modelos Antiguos A',lduRowsForGroup(devices,'A'),'a')}${dashboardStateSection('📈 Estados — 🟧 Modelos Antiguos B',lduRowsForGroup(devices,'B'),'b')}<section class="section dashboard-incidents"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="dashboardExportRows(${JSON.stringify(incidents).replaceAll('"','&quot;')},'incidencias')">📄 Excel</button><button class="btn secondary" onclick="navigate('incidents')">Ver todo →</button></div></div><div class="cards compact">${dashboardIncidentCards(incidents)}</div></section>${dashboardMapSection(devices)}${stockSummaryDashboard(devices)}<div class="dashboard-bottom"><section class="section"><div class="section-head"><h2>📱 Últimos dispositivos</h2></div>${dashboardTable(devices.slice(-5).reverse(),['imei','modelo','responsable','estado'])}</section><section class="section"><div class="section-head"><h2>⚠️ Incidencias recientes</h2></div>${dashboardTable(incidents.slice(-5).reverse(),['imei_original','tipo','nombre','estado_proceso'])}</section></div>`}catch(error){document.querySelector('#connection-status').textContent='Error de conexión';document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>No se pudo cargar el Dashboard</h2></div><div class="error">${esc(error.message)}</div><div class="section-body"><button class="btn" onclick="renderDashboard()">Reintentar</button></div></section>`}}
function stockSummaryDashboard(rows){return `<section class="section stock-summary"><div class="section-head"><h2>📦 Resumen de Stock por Modelo</h2><button class="btn secondary" onclick="renderDashboard()">🔄 Actualizar</button></div>${stockGroup('✅ Inventario LDU',lduRowsForGroup(rows,'inventory'),'inventory')}${stockGroup('🟦 Modelos Antiguos A',lduRowsForGroup(rows,'A'),'a')}${stockGroup('🟧 Modelos Antiguos B',lduRowsForGroup(rows,'B'),'b')}</section>`}
const LDU_INCIDENT_COLUMNS=[['imei_original','IMEI Original'],['tipo','Tipo'],['imei_nuevo','IMEI Nuevo'],['marca','Marca'],['modelo','Modelo'],['n_linea','N° Línea'],['responsable','Responsable'],['dni','DNI'],['cargo','Cargo'],['tipo_uso','Tipo Uso'],['supervisor','Supervisor'],['zona','Zona'],['cuenta','Cuenta'],['departamento','Departamento'],['city','City'],['canal','Canal'],['tienda','Tienda'],['fecha_incidente','Fecha del Incidente'],['valor','Monto S/'],['doc_autorizacion','Doc. Autorización'],['modalidad','Modalidad'],['estado_proceso','Estado'],['doc_adjunto','Doc. Adjunto']];
function incidentRow(row){return `<tr>${LDU_INCIDENT_COLUMNS.map(([key])=>`<td>${key==='tipo'?badge(row[key]):key==='estado_proceso'?badge(row[key]||'Pendiente'):esc(row[key]||'—')}</td>`).join('')}<td class="row-actions"><button title="Ver" data-incident-action="view">👁️</button><button title="Editar" data-incident-action="edit">✎️</button><button title="Historial" data-incident-action="history">📋</button><button title="Documento" data-incident-action="document">📄</button><button title="Eliminar" data-incident-action="delete">✕</button></td></tr>`}
function incidentSelect(label,name,options){return `<label><span>${label}</span><select class="select" name="${name}"><option value="">Seleccionar...</option>${options.map(option=>`<option>${option}</option>`).join('')}</select></label>`}
function incidentInput(label,name,type='text',placeholder=''){return `<label><span>${label}</span><input class="input" name="${name}" type="${type}" placeholder="${placeholder}"></label>`}
function openIncidentForm(){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card device-form-card"><div class="section-head"><h2>⚠️ Nueva Incidencia</h2><button class="btn secondary" id="close-incident">✕</button></div><form id="new-incident-form" class="device-form"><h3>⚡ Evento</h3><div class="form-grid">${incidentInput('IMEI Original *','imei_original','text','15-17 dígitos')}${incidentSelect('Tipo *','tipo',['Daño','Pérdida','Robo','Otro'])}${incidentInput('IMEI Nuevo','imei_nuevo')}${incidentInput('Marca','marca')}${incidentInput('Modelo','modelo')}${incidentInput('N° Línea','n_linea')}${incidentInput('Fecha del Incidente','fecha_incidente','date')}${incidentInput('Monto S/','valor','number')}</div><h3>👤 Colaborador</h3><div class="form-grid">${incidentInput('Nombre completo','responsable')}${incidentInput('DNI','dni')}${incidentInput('Cargo','cargo')}${incidentInput('Supervisor','supervisor')}</div><h3>⚙️ Proceso</h3><div class="form-grid">${incidentSelect('Tipo de Uso','tipo_uso',['Exhibición','Promotor','Red de Trabajo','Equipo en Mano','Custodia'])}${incidentSelect('Modalidad','modalidad',['Sin definir','Pago','Descuento','Reposición','Pendiente'])}${incidentSelect('Estado','estado_proceso',['Pendiente','En Curso','Finalizado','Descontado'])}${incidentSelect('Doc. Autorización','doc_autorizacion',['No','Sí'])}${incidentInput('Zona','zona')}${incidentInput('Cuenta','cuenta')}${incidentInput('Departamento','departamento')}${incidentInput('City','city')}${incidentInput('Canal','canal')}${incidentInput('Tienda','tienda')}<label class="full-field"><span>Observaciones</span><textarea class="input" name="observaciones"></textarea></label><label class="full-field"><span>📎 Documentos adjuntos (PDF, XLSX, XLS)</span><input class="input" type="file" name="doc_adjunto" accept=".pdf,.xlsx,.xls"></label></div><div class="form-actions"><button class="btn secondary" type="button" id="cancel-incident">Cancelar</button><button class="btn" type="submit">💾 Guardar</button></div><div id="incident-form-message"></div></form></aside>`;document.body.appendChild(drawer);const close=()=>drawer.remove();drawer.querySelector('#close-incident').addEventListener('click',close);drawer.querySelector('#cancel-incident').addEventListener('click',close);drawer.querySelector('#new-incident-form').addEventListener('submit',async event=>{event.preventDefault();const msg=drawer.querySelector('#incident-form-message'),form=new FormData(event.target),incident=Object.fromEntries(form.entries());delete incident.doc_adjunto;msg.textContent='Guardando...';const result=await api('createIncident',{incident,userId:'web-user'});if(result.status==='ok'){close();renderIncidents()}else msg.textContent=result.message||'No se pudo guardar la incidencia.'})}
async function renderIncidents(){document.querySelector('#app').innerHTML='<div class="loading">⏳ Cargando incidencias...</div>';try{const response=await api('listIncidents');if(response.status!=='ok')throw new Error(response.message||'Error de API');const rows=response.data||[],norm=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),status=rows.reduce((a,r)=>{const k=norm(r.estado_proceso||'pendiente');a[k]=(a[k]||0)+1;return a},{}),types=rows.reduce((a,r)=>{const k=norm(r.tipo);a[k]=(a[k]||0)+1;return a},{});document.querySelector('#app').innerHTML=`<div class="cards dashboard-overview">${dashboardMetric('📊 TOTAL',rows.length)}${dashboardMetric('⏳ PENDIENTE',status.pendiente||0)}${dashboardMetric('🔄 EN CURSO',status['en curso']||0)}${dashboardMetric('💥 DAÑADOS',types.dano||0)}${dashboardMetric('🔎 PERDIDOS',types.perdida||0)}${dashboardMetric('🕵️ ROBADOS',types.robo||0)}${dashboardMetric('📌 OTROS',types.otro||0)}${dashboardMetric('🔁 REPOSICIÓN',types.reposicion||0)}${dashboardMetric('↩️ DEVOLUCIÓN',types.devolucion||0)}${dashboardMetric('💰 VALOR TOTAL','S/ '+rows.reduce((n,r)=>n+Number(r.valor||0),0).toFixed(2))}</div><section class="section"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="dashboardExportRows(window.__LDU_INCIDENTS||[],'incidencias')">📄 Excel</button><button class="btn" onclick="openIncidentForm()">＋ Nueva</button></div></div><div class="table-wrap module-table"><table><thead><tr>${LDU_INCIDENT_COLUMNS.map(c=>`<th>${c[1]}</th>`).join('')}<th>Acc.</th></tr></thead><tbody>${rows.length?rows.map(incidentRow).join(''):`<tr><td colspan="25" class="empty">Sin incidencias</td></tr>`}</tbody></table></div></section>`;window.__LDU_INCIDENTS=rows}catch(error){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>No se pudo cargar Incidencias</h2></div><div class="error">${esc(error.message)}</div><div class="section-body"><button class="btn" onclick="renderIncidents()">Reintentar</button></div></section>`}}
